"""Decorator that traces function calls and builds a call graph."""

import functools
import time
from collections import defaultdict
from dataclasses import dataclass, field


@dataclass
class CallNode:
    """A node in the call graph representing a traced function."""

    name: str
    call_count: int = 0
    total_time: float = 0.0
    children: dict[str, "CallNode"] = field(default_factory=dict)


class CallGraph:
    """Collects call relationships from traced functions."""

    def __init__(self):
        self.root = CallNode(name="<root>")
        self._call_stack: list[CallNode] = [self.root]

    def enter(self, name: str) -> CallNode:
        parent = self._call_stack[-1]
        if name not in parent.children:
            parent.children[name] = CallNode(name=name)
        node = parent.children[name]
        node.call_count += 1
        self._call_stack.append(node)
        return node

    def exit(self, duration: float) -> None:
        if len(self._call_stack) > 1:
            node = self._call_stack.pop()
            node.total_time += duration

    def get_edges(self) -> list[tuple[str, str, int]]:
        """Return edges as (parent, child, call_count)."""
        edges: list[tuple[str, str, int]] = []
        self._collect_edges(self.root, edges)
        return edges

    def _collect_edges(self, node: CallNode, edges: list) -> None:
        for child in node.children.values():
            edges.append((node.name, child.name, child.call_count))
            self._collect_edges(child, edges)

    def get_node(self, name: str) -> CallNode | None:
        return self._find_node(self.root, name)

    def _find_node(self, node: CallNode, name: str) -> CallNode | None:
        if node.name == name:
            return node
        for child in node.children.values():
            found = self._find_node(child, name)
            if found:
                return found
        return None

    def print_graph(self, node: CallNode | None = None, indent: int = 0) -> None:
        """Print the call graph as a tree."""
        if node is None:
            node = self.root
        prefix = "  " * indent
        if node.name == "<root>":
            label = "<root>"
        else:
            label = f"{node.name}  (calls={node.call_count}, time={node.total_time*1000:.2f}ms)"
        print(f"{prefix}{label}")
        for child in node.children.values():
            self.print_graph(child, indent + 1)


# Module-level default graph for the @trace decorator
_default_graph = CallGraph()


def get_graph() -> CallGraph:
    """Return the default call graph used by @trace."""
    return _default_graph


def reset_graph() -> None:
    """Reset the default call graph."""
    global _default_graph
    _default_graph = CallGraph()


def trace(func=None, *, graph: CallGraph | None = None):
    """Decorator that records function calls into a CallGraph.

    Usage:
        @trace
        def my_func():
            ...

        @trace(graph=my_graph)
        def other_func():
            ...
    """

    def decorator(fn):
        target_graph = graph or _default_graph

        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            node = target_graph.enter(fn.__qualname__)
            start = time.perf_counter()
            try:
                return fn(*args, **kwargs)
            finally:
                target_graph.exit(time.perf_counter() - start)

        return wrapper

    if func is not None:
        return decorator(func)
    return decorator


# ---------------------------------------------------------------------------
# Usage examples
# ---------------------------------------------------------------------------


def example_basic():
    """Basic usage: decorate functions and print the graph."""
    reset_graph()

    @trace
    def parse(data):
        return [x.strip() for x in data.split(",")]

    @trace
    def validate(items):
        return all(len(item) > 0 for item in items)

    @trace
    def process(data):
        items = parse(data)
        if validate(items):
            return [item.upper() for item in items]
        return []

    @trace
    def pipeline(raw_inputs):
        results = []
        for raw in raw_inputs:
            results.extend(process(raw))
        return results

    pipeline(["hello, world", "foo, bar, baz", "single"])

    print("=== Call Graph ===")
    get_graph().print_graph()
    print()


def example_edges():
    """Extract edges for external analysis."""
    reset_graph()

    @trace
    def a():
        pass

    @trace
    def b():
        a()
        a()

    @trace
    def c():
        b()

    c()
    c()

    print("=== Edges ===")
    for parent, child, count in get_graph().get_edges():
        print(f"  {parent} -> {child}  ({count} calls)")
    print()


def example_custom_graph():
    """Use a dedicated graph for isolated tracing."""
    g = CallGraph()

    @trace(graph=g)
    def foo():
        bar()

    @trace(graph=g)
    def bar():
        pass

    foo()
    foo()

    print("=== Custom Graph ===")
    g.print_graph()
    print()


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------


def _test_basic_tracing():
    """Traced functions appear in the graph."""
    reset_graph()

    @trace
    def parse(data):
        return data.split(",")

    @trace
    def validate(items):
        return len(items) > 0

    @trace
    def process(data):
        items = parse(data)
        validate(items)
        return items

    process("a,b,c")

    names = {child for _, child, _ in get_graph().get_edges()}
    assert any("parse" in n for n in names), f"Expected 'parse' in {names}"
    assert any("validate" in n for n in names), f"Expected 'validate' in {names}"
    assert any("process" in n for n in names), f"Expected 'process' in {names}"


def _test_call_counts():
    """Call counts reflect actual invocations."""
    reset_graph()

    @trace
    def a():
        pass

    @trace
    def b():
        a()
        a()

    @trace
    def c():
        b()

    c()
    c()

    edges = {child: count for _, child, count in get_graph().get_edges()}
    c_names = [n for n in edges if n.endswith(".c")]
    b_names = [n for n in edges if n.endswith(".b")]
    a_names = [n for n in edges if n.endswith(".a")]

    assert c_names, f"Expected c in edges: {edges}"
    assert b_names, f"Expected b in edges: {edges}"
    assert a_names, f"Expected a in edges: {edges}"

    assert edges[c_names[0]] == 2, f"c: expected 2, got {edges[c_names[0]]}"
    assert edges[b_names[0]] == 2, f"b: expected 2, got {edges[b_names[0]]}"
    assert edges[a_names[0]] == 4, f"a: expected 4, got {edges[a_names[0]]}"


def _test_graph_structure():
    """The graph captures parent-child relationships."""
    reset_graph()

    @trace
    def parent():
        child_a()
        child_b()

    @trace
    def child_a():
        grandchild()

    @trace
    def child_b():
        pass

    @trace
    def grandchild():
        pass

    parent()

    edges = {(p, c) for p, c, _ in get_graph().get_edges()}
    names = {c for _, c in edges}

    parent_name = [n for n in names if n.endswith(".parent")][0]
    child_a_name = [n for n in names if n.endswith(".child_a")][0]
    child_b_name = [n for n in names if n.endswith(".child_b")][0]
    grandchild_name = [n for n in names if n.endswith(".grandchild")][0]

    assert (parent_name, child_a_name) in edges
    assert (parent_name, child_b_name) in edges
    assert (child_a_name, grandchild_name) in edges


def _test_timing_recorded():
    """Nodes accumulate non-zero time."""
    reset_graph()

    @trace
    def slow():
        time.sleep(0.01)

    slow()

    edges = get_graph().get_edges()
    slow_names = [c for _, c, _ in edges if "slow" in c]
    assert slow_names, f"Expected 'slow' in edges"
    node = get_graph().get_node(slow_names[0])
    assert node is not None
    assert node.total_time > 0, f"Expected >0 time, got {node.total_time}"


def _test_custom_graph():
    """A dedicated graph isolates traces from the default graph."""
    reset_graph()
    g = CallGraph()

    @trace(graph=g)
    def isolated():
        pass

    isolated()

    assert len(g.get_edges()) == 1
    assert len(get_graph().get_edges()) == 0


def _test_preserves_return_value():
    """Decorated functions still return their value."""
    reset_graph()

    @trace
    def add(a, b):
        return a + b

    result = add(3, 4)
    assert result == 7, f"Expected 7, got {result}"


def _test_preserves_metadata():
    """functools.wraps preserves function name and docstring."""
    reset_graph()

    @trace
    def documented():
        """My docstring."""
        pass

    assert documented.__name__ == "documented"
    assert documented.__doc__ == "My docstring."


def _test_empty_trace():
    """No calls produces an empty graph."""
    reset_graph()

    @trace
    def unused():
        pass

    assert len(get_graph().root.children) == 0
    assert get_graph().get_edges() == []


def run_tests():
    tests = [
        _test_basic_tracing,
        _test_call_counts,
        _test_graph_structure,
        _test_timing_recorded,
        _test_custom_graph,
        _test_preserves_return_value,
        _test_preserves_metadata,
        _test_empty_trace,
    ]
    passed = 0
    failed = 0
    for test in tests:
        name = test.__name__
        try:
            test()
            print(f"  PASS  {name}")
            passed += 1
        except Exception as e:
            print(f"  FAIL  {name}: {e}")
            failed += 1

    print(f"\n{passed} passed, {failed} failed out of {len(tests)}")
    return failed == 0


if __name__ == "__main__":
    import sys

    if len(sys.argv) > 1 and sys.argv[1] == "test":
        success = run_tests()
        sys.exit(0 if success else 1)
    else:
        example_basic()
        example_edges()
        example_custom_graph()
